(function() {
    'use strict';

    var countdownInterval = null;

    // ✅ MELAKA DATA - Verified JAKIM Official Source
    var melaka = [
        {day:'Khamis', r:1,  date:'19 Feb', imsak:'06:05', berbuka:'19:28'},
        {day:'Jumaat', r:2,  date:'20 Feb', imsak:'06:05', berbuka:'19:28'},
        {day:'Sabtu',  r:3,  date:'21 Feb', imsak:'06:05', berbuka:'19:28'},
        {day:'Ahad',   r:4,  date:'22 Feb', imsak:'06:05', berbuka:'19:28'},
        {day:'Isnin',  r:5,  date:'23 Feb', imsak:'06:05', berbuka:'19:28'},
        {day:'Selasa', r:6,  date:'24 Feb', imsak:'06:04', berbuka:'19:28'},
        {day:'Rabu',   r:7,  date:'25 Feb', imsak:'06:04', berbuka:'19:28'},
        {day:'Khamis', r:8,  date:'26 Feb', imsak:'06:04', berbuka:'19:27'},
        {day:'Jumaat', r:9,  date:'27 Feb', imsak:'06:04', berbuka:'19:27'},
        {day:'Sabtu',  r:10, date:'28 Feb', imsak:'06:04', berbuka:'19:27'},
        {day:'Ahad',   r:11, date:'1 Mac',  imsak:'06:04', berbuka:'19:27'},
        {day:'Isnin',  r:12, date:'2 Mac',  imsak:'06:03', berbuka:'19:27'},
        {day:'Selasa', r:13, date:'3 Mac',  imsak:'06:03', berbuka:'19:27'},
        {day:'Rabu',   r:14, date:'4 Mac',  imsak:'06:03', berbuka:'19:27'},
        {day:'Khamis', r:15, date:'5 Mac',  imsak:'06:03', berbuka:'19:26'},
        {day:'Jumaat', r:16, date:'6 Mac',  imsak:'06:02', berbuka:'19:26'},
        {day:'Sabtu',  r:17, date:'7 Mac',  imsak:'06:02', berbuka:'19:26'},
        {day:'Ahad',   r:18, date:'8 Mac',  imsak:'06:02', berbuka:'19:26'},
        {day:'Isnin',  r:19, date:'9 Mac',  imsak:'06:02', berbuka:'19:26'},
        {day:'Selasa', r:20, date:'10 Mac', imsak:'06:01', berbuka:'19:26'},
        {day:'Rabu',   r:21, date:'11 Mac', imsak:'06:01', berbuka:'19:25'},
        {day:'Khamis', r:22, date:'12 Mac', imsak:'06:01', berbuka:'19:25'},
        {day:'Jumaat', r:23, date:'13 Mac', imsak:'06:00', berbuka:'19:25'},
        {day:'Sabtu',  r:24, date:'14 Mac', imsak:'06:00', berbuka:'19:25'},
        {day:'Ahad',   r:25, date:'15 Mac', imsak:'06:00', berbuka:'19:25'},
        {day:'Isnin',  r:26, date:'16 Mac', imsak:'06:00', berbuka:'19:24'},
        {day:'Selasa', r:27, date:'17 Mac', imsak:'05:59', berbuka:'19:24'},
        {day:'Rabu',   r:28, date:'18 Mac', imsak:'05:59', berbuka:'19:24'},
        {day:'Khamis', r:29, date:'19 Mac', imsak:'05:58', berbuka:'19:24'},
        {day:'Jumaat', r:30, date:'20 Mac', imsak:'05:58', berbuka:'19:23'}
    ];

    function getDayIndex() {
        var ramadanStart = new Date(2026, 1, 19);
        var today = new Date();
        today.setHours(0,0,0,0);
        ramadanStart.setHours(0,0,0,0);
        return Math.floor((today - ramadanStart) / 86400000);
    }

    function renderTable() {
        var tbody = document.getElementById('ilmxMlkTableBody');
        if (!tbody) return;
        var idx = getDayIndex();
        var html = '';
        melaka.forEach(function(row, i) {
            var isToday = (i === idx);
            html += '<tr' + (isToday ? ' class="ilmx-today"' : '') + '>';
            html += '<td>' + row.day + (isToday ? ' 🌙' : '') + '</td>';
            html += '<td><strong>' + row.r + '</strong></td>';
            html += '<td>' + row.date + ' 2026</td>';
            html += '<td class="ilmx-time-col">' + row.imsak + '</td>';
            html += '<td class="ilmx-time-col">' + row.berbuka + '</td>';
            html += '</tr>';
        });
        tbody.innerHTML = html;
        // Scroll to today
        if (idx >= 0 && idx < 30) {
            setTimeout(function() {
                var todayRow = tbody.querySelector('.ilmx-today');
                if (todayRow) todayRow.scrollIntoView({block:'center', behavior:'smooth'});
            }, 300);
        }
    }

    function updateCards() {
        var idx = getDayIndex();
        var imsakEl = document.getElementById('ilmxMlkImsakCard');
        var bukaEl = document.getElementById('ilmxMlkBukaCard');
        if (idx >= 0 && idx < 30) {
            if (imsakEl) imsakEl.textContent = melaka[idx].imsak;
            if (bukaEl) bukaEl.textContent = melaka[idx].berbuka;
        }
    }

    function startCountdown() {
        if (countdownInterval) clearInterval(countdownInterval);
        var idx = getDayIndex();
        var todayEl = document.getElementById('ilmxMlkToday');

        if (idx < 0 || idx >= 30) {
            if (todayEl) todayEl.innerHTML = '<strong>⭐ Ramadan 2026 dijangka bermula 19 Februari 2026 (Khamis)</strong>';
            return;
        }

        var d = melaka[idx];
        var berbukaT = d.berbuka.split(':');
        var now = new Date();
        var target = new Date(now.getFullYear(), now.getMonth(), now.getDate(), parseInt(berbukaT[0]), parseInt(berbukaT[1]), 0);

        if (todayEl) todayEl.innerHTML = '<strong>Hari ini (' + d.r + ' Ramadan ' + d.date + '):</strong> Imsak ' + d.imsak + ' | Berbuka ' + d.berbuka;

        countdownInterval = setInterval(function() {
            var n = new Date();
            var diff = target - n;
            if (diff <= 0) {
                document.getElementById('ilmxMlkHours').textContent = '00';
                document.getElementById('ilmxMlkMinutes').textContent = '00';
                document.getElementById('ilmxMlkSeconds').textContent = '00';
                if (todayEl) todayEl.innerHTML = '🌙 <strong>Sudah masuk waktu berbuka! Selamat berbuka puasa!</strong>';
                clearInterval(countdownInterval);
                return;
            }
            var h = Math.floor(diff / 3600000);
            var m = Math.floor((diff % 3600000) / 60000);
            var s = Math.floor((diff % 60000) / 1000);
            document.getElementById('ilmxMlkHours').textContent = String(h).padStart(2,'0');
            document.getElementById('ilmxMlkMinutes').textContent = String(m).padStart(2,'0');
            document.getElementById('ilmxMlkSeconds').textContent = String(s).padStart(2,'0');
        }, 1000);
    }

    document.addEventListener('DOMContentLoaded', function() {
        renderTable();
        updateCards();
        startCountdown();
    });

    var _c = 'KGMpIDIwMjYgSWxtdUFsYW0gTWVsYWthIERhcnVsIEF6aW0=';
})();
